// GENERATED by clients/emvia/derive_flow.py from fulltest.js — do not edit by hand.
// Edit your flow script, then run:  python -m clients.emvia.derive_flow
// Run by clients/emvia/tms_create.py inside the TMS page: evaluate(<this function>, job).

// TMS — full flow for one shipment:
//   1) General  2) Attach file  3) Lines  4) Order Cargo  5) Calculate Revenues  6) Copy Order
//   7) Close "Copy Orders Overviews" (orders noted)  8) read File No.  9) Back  10) filter list by File No.
//   11) open 1st order (⋮ → Edit) → Container No. + Seal No. → check Lines → Next → … for every container
// Run from JS File Runner with an empty TMS Order Card open (edit mode). Output: page Console (F12).

async (__JOB__) => {
  // =====================================================================
  //  JOB DATA — handed in by the platform (clients/emvia/tms_create.py); nothing is typed in here
  // =====================================================================
  const DATA = __JOB__.data;                         // General fields, file, lines, cargo (dates d/MM/yyyy)
  const CALC_REVENUES = __JOB__.calcRevenues !== false;   // Tariffs → Calculate Revenues
  const CONTAINERS = __JOB__.containers;             // ONE ENTRY PER CONTAINER: [{containerNo, sealNo}]
  const COPIES = CONTAINERS.length - 1;              // orders = containers, copies = containers - 1
  const DEADLINE = Date.now() + (__JOB__.timeoutMs || 15 * 60 * 1000);   // hard stop for the whole run
  const RESULT = { orders: {}, fileNo: null };       // handed back: container no. -> TMS order no.; File No. (optional)

  // Lines check after editing: columns that must be filled per Action Code
  const REQUIRED = {
    "DEPOT OUT": ["Address No.", "Address Name", "Order Line Ref 1", "Booked DateTime From", "Closing Date Time"],
    "DEPOT IN":  ["Address No.", "Address Name", "Order Line Ref 1", "Booked DateTime From", "Closing Date Time"],
    "*":         ["Address No.", "Address Name"],
  };

  // =====================================================================
  //  FRAME + COMMON HELPERS
  // =====================================================================
  const TOP = globalThis;
  function findBcWindow() {
    const has = w => { try { return !!w.document.querySelector(".ms-nav-edit-control-container"); } catch { return false; } };
    const walk = w => {
      if (has(w)) return w;
      for (const f of w.document.querySelectorAll("iframe")) {
        try { const r = walk(f.contentWindow); if (r) return r; } catch {}
      }
      return null;
    };
    return walk(TOP);
  }
  let W = findBcWindow();
  if (!W) return { ok: false, stopped: "BC form not found. Open the TMS Order Card first.",
                   orders: {}, fileNo: null, log: [] };
  let window = W, document = W.document;
  let { KeyboardEvent, MouseEvent, PointerEvent, FocusEvent, InputEvent, Event, HTMLInputElement } = W;
  const rebind = w => {
    W = w; window = w; document = w.document;
    ({ KeyboardEvent, MouseEvent, PointerEvent, FocusEvent, InputEvent, Event, HTMLInputElement } = w);
  };
  // find the frame whose document passes test(doc)
  function findWindow(test) {
    const walk = w => {
      try { if (test(w.document)) return w; } catch {}
      try { for (const f of w.document.querySelectorAll("iframe")) { const r = walk(f.contentWindow); if (r) return r; } } catch {}
      return null;
    };
    return walk(TOP);
  }
  const hasSized = (doc, sel) => [...doc.querySelectorAll(sel)].some(e => {
    const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2;
  });

  // Every wait/poll in the script goes through here, so passing DEADLINE stops the whole run.
  const wait = ms => {
    if (Date.now() > DEADLINE) throw new Error("Job time limit reached");
    return new Promise(r => setTimeout(r, ms));
  };
  const until = async (fn, timeout = 8000, step = 150) => {
    const t = Date.now();
    while (Date.now() - t < timeout) { const v = fn(); if (v) return v; await wait(step); }
    return null;
  };
  const norm = s => (s || "").replace(/\s+/g, " ").trim().toLowerCase();
  const vis  = el => !!el && el.offsetParent !== null && el.getClientRects().length > 0;
  const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;

  const keyEv = (el, type, key, code, keyCode) => el.dispatchEvent(new KeyboardEvent(type, {
    key, code, keyCode, which: keyCode, bubbles: true, cancelable: true, composed: true }));
  const clickEl = el => ["mousedown", "mouseup", "click"].forEach(t =>
    el.dispatchEvent(new MouseEvent(t, { bubbles: true, cancelable: true, view: window, button: 0 })));
  const realClick = el => {
    const r = el.getBoundingClientRect();
    const o = { bubbles: true, cancelable: true, view: window, button: 0, buttons: 1,
                clientX: r.left + Math.min(10, r.width / 2), clientY: r.top + r.height / 2 };
    if (PointerEvent) el.dispatchEvent(new PointerEvent("pointerdown", { ...o, pointerType: "mouse" }));
    el.dispatchEvent(new MouseEvent("mousedown", o));
    if (PointerEvent) el.dispatchEvent(new PointerEvent("pointerup", { ...o, buttons: 0, pointerType: "mouse" }));
    el.dispatchEvent(new MouseEvent("mouseup", { ...o, buttons: 0 }));
    el.dispatchEvent(new MouseEvent("click", { ...o, buttons: 0 }));
  };
  const doubleClick = el => {
    const r = el.getBoundingClientRect();
    const base = { bubbles: true, cancelable: true, view: window, button: 0,
                   clientX: r.left + r.width / 2, clientY: r.top + r.height / 2 };
    for (const detail of [1, 2]) {
      const o = { ...base, detail };
      el.dispatchEvent(new MouseEvent("mousedown", { ...o, buttons: 1 }));
      el.dispatchEvent(new MouseEvent("mouseup", o));
      el.dispatchEvent(new MouseEvent("click", o));
    }
    el.dispatchEvent(new MouseEvent("dblclick", { ...base, detail: 2 }));
  };
  const focusIn = el => {
    el.focus();
    el.dispatchEvent(new FocusEvent("focus",   { bubbles: false }));
    el.dispatchEvent(new FocusEvent("focusin", { bubbles: true }));
    clickEl(el);
  };
  const focusOut = el => {
    el.dispatchEvent(new FocusEvent("blur",     { bubbles: false }));
    el.dispatchEvent(new FocusEvent("focusout", { bubbles: true }));
    el.blur();
  };
  const blurActive = () => {
    const a = document.activeElement;
    if (a && a !== document.body) focusOut(a);
  };
  const pressTab   = el => { keyEv(el, "keydown", "Tab", "Tab", 9);     keyEv(el, "keyup", "Tab", "Tab", 9); };
  const pressEnter = el => { keyEv(el, "keydown", "Enter", "Enter", 13); keyEv(el, "keyup", "Enter", "Enter", 13); };

  async function typeText(el, value) {
    focusIn(el);
    await wait(100);
    setter.call(el, "");
    el.dispatchEvent(new Event("input", { bubbles: true }));
    for (const ch of value) {
      keyEv(el, "keydown", ch, "", ch.charCodeAt(0));
      keyEv(el, "keypress", ch, "", ch.charCodeAt(0));
      setter.call(el, el.value + ch);
      el.dispatchEvent(new InputEvent("input", { bubbles: true, data: ch, inputType: "insertText" }));
      keyEv(el, "keyup", ch, "", ch.charCodeAt(0));
      await wait(20);
    }
    el.dispatchEvent(new Event("change", { bubbles: true }));
  }

  // ---- inline lookup dropdowns ----
  const lookupTables = () =>
    [...document.querySelectorAll("table.ms-nav-grid-data-table")].filter(t =>
      /^lookupform/i.test(t.querySelector("caption")?.textContent || "") && vis(t));
  const findDropdownRow = code => {
    for (const t of lookupTables())
      for (const r of t.querySelectorAll("tbody tr[role=row]")) {
        const a = r.querySelector("td a.stringcontrol-read");
        if (a && norm(a.textContent) === norm(code)) return r;
      }
    return null;
  };
  const anyDropdownOpen = () => lookupTables().length > 0;

  // ---- date pickers ----
  const isCalendar = el => /go to today|selected date/i.test(el.innerText || "");
  const openCalendars = () =>
    [...document.querySelectorAll('[role="dialog"], .ms-Callout, .ms-Layer')].filter(el => vis(el) && isCalendar(el));
  async function closeDatePicker() {
    for (let i = 0; i < 3 && openCalendars().length; i++) {
      const cal = openCalendars()[0];
      keyEv(cal, "keydown", "Escape", "Escape", 27);
      keyEv(cal, "keyup",   "Escape", "Escape", 27);
      if (await until(() => !openCalendars().length, 800)) break;
      const neutral = getInput("OrderDescription2") || getInput("OrderDescription");
      if (neutral) { focusIn(neutral); await wait(150); focusOut(neutral); }
      await until(() => !openCalendars().length, 800);
    }
  }

  const log = [];
  let CUR = 0, CUR_NO = "";
  const L = (section, o) => log.push({ Order: CUR, No: CUR_NO, Section: section, ...o });

  // =====================================================================
  //  1) GENERAL TAB
  // =====================================================================
  const container = (cn, caption) => {
    const byCn = [...document.querySelectorAll(`.ms-nav-edit-control-container[controlname="${cn}"]`)].filter(vis);
    if (byCn.length) return byCn[byCn.length - 1];
    if (!caption) return null;
    const byCap = [...document.querySelectorAll(".ms-nav-edit-control-container")].filter(c =>
      vis(c) && norm(c.querySelector(".ms-nav-edit-control-caption")?.innerText) === norm(caption));
    return byCap[byCap.length - 1] || null;
  };
  const getInput = (cn, caption) => {
    const el = container(cn, caption)?.querySelector("input:not([type=checkbox]):not([type=hidden]), select");
    return el && !el.disabled && !el.readOnly ? el : null;
  };

  async function commitText(el, value) { await typeText(el, value); pressTab(el); await wait(100); focusOut(el); }
  async function commitSelect(el, text) {
    const opt = [...el.options].find(o => norm(o.textContent) === norm(text));
    if (!opt) throw new Error("Option not found: " + text);
    focusIn(el);
    el.value = opt.value;
    el.dispatchEvent(new Event("input",  { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
    await wait(100);
    focusOut(el);
  }
  async function commitLookup(el, value) {
    await typeText(el, value);
    const row = await until(() => findDropdownRow(value), 4000);
    if (!row) { pressTab(el); await wait(100); focusOut(el); return; }
    clickEl(row.querySelector("td a.stringcontrol-read"));
    if (!(await until(() => !anyDropdownOpen(), 2500))) {
      const link = findDropdownRow(value)?.querySelector("td a.stringcontrol-read");
      if (link) clickEl(link);
      await until(() => !anyDropdownOpen(), 2500);
    }
    await wait(200);
    focusOut(el);
  }

  const findTLDialog = () => [...document.querySelectorAll("main.task-dialog")]
    .find(m => m.querySelector('[title="TMS Tradelanes"]') && vis(m));
  const anyDialog = () => [...document.querySelectorAll("main.task-dialog")].some(vis);

  async function showMore() {
    const btn = [...document.querySelectorAll("a, button, span")]
      .find(e => norm(e.innerText) === "show more" && vis(e));
    if (btn) { clickEl(btn); await wait(1000); }
  }

  async function fill(label, cn, value, opts = {}) {
    if (!value) return;
    const cap = opts.caption || label;
    let el = await until(() => getInput(cn, cap), opts.timeout || 4000);
    if (!el) { await showMore(); el = await until(() => getInput(cn, cap), 3000); }
    if (!el) { L("General", { Field: label, Value: value, Status: "NOT FOUND / READ-ONLY" }); return; }
    try {
      if (el.tagName === "SELECT") await commitSelect(el, value);
      else if (opts.lookup)        await commitLookup(el, value);
      else                         await commitText(el, value);
      await wait(900);
      if (opts.date) await closeDatePicker();
      const now = getInput(cn, cap);
      const shown = now?.tagName === "SELECT" ? now.options[now.selectedIndex]?.textContent.trim() : now?.value;
      const ok = opts.date ? norm(shown).includes(norm(value)) : norm(shown) === norm(value);
      L("General", { Field: label, Value: value, Actual: shown, Status: ok ? "OK" : "CHECK" });
      if (anyDropdownOpen()) {                     // close a leftover dropdown with Escape
        const i = getInput(cn, cap) || el;
        keyEv(i, "keydown", "Escape", "Escape", 27); keyEv(i, "keyup", "Escape", "Escape", 27);
        await until(() => !anyDropdownOpen(), 1500);
      }
      if (anyDialog() || anyDropdownOpen()) L("General", { Field: label, Status: "LOOKUP STILL OPEN" });
    } catch (e) { L("General", { Field: label, Value: value, Status: e.message }); }
  }

  const tradeLaneShown = () => {
    const c = container("TradeLaneNo");
    return c ? norm((c.innerText || "") + " " + (c.querySelector("input")?.value || "")) : "";
  };

  async function customerAndTradelane(R) {
    let cust = await until(() => getInput("CustomerNo") || getInput("CustomerName"), 5000);
    if (!cust) { await showMore(); cust = await until(() => getInput("CustomerNo") || getInput("CustomerName"), 3000); }
    if (!cust) throw new Error("Customer No. input not found (is the card in edit mode?)");

    await typeText(cust, R.customer);
    pressEnter(cust); await wait(100); focusOut(cust);
    let dlg = await until(findTLDialog, 5000);
    if (!dlg) { focusIn(cust); pressTab(cust); await wait(100); focusOut(cust); dlg = await until(findTLDialog, 5000); }
    if (!dlg) {
      const next = getInput("OrderDescription");
      if (next) { focusIn(next); await wait(100); focusOut(next); }
      dlg = await until(findTLDialog, 5000);
    }
    if (!dlg) throw new Error("TMS Tradelanes dialog did not open.");
    console.log("✅ Tradelane popup open");

    const findRow = () => {
      const d = findTLDialog();
      return d && [...d.querySelectorAll("table.ms-nav-grid-data-table tbody tr[role=row]")]
        .find(r => [...r.querySelectorAll("td a.stringcontrol-read")].some(a => a.textContent.trim() === R.tradelane));
    };
    const noLink = () => [...(findRow()?.querySelectorAll("td a.stringcontrol-read") || [])]
      .find(a => a.textContent.trim() === R.tradelane);
    const isSelected = r => !!r && (r.getAttribute("aria-selected") === "true" || r.classList.contains("real-current"));
    const getOkBtn = () => {
      const d = findTLDialog();
      return d && (d.querySelector(".ms-nav-actionbar-container button.highlight-btn") ||
        [...d.querySelectorAll(".ms-nav-actionbar-container button")].find(b => norm(b.innerText) === "ok"));
    };
    const isClosed = t => until(() => !findTLDialog(), t);

    if (!(await until(findRow, 8000))) throw new Error("Trade lane row not found: " + R.tradelane);
    await wait(500);

    let closed = false;
    for (let i = 1; i <= 3 && !closed; i++) {
      const link = noLink();
      if (!link) { closed = !!(await isClosed(500)); break; }
      link.scrollIntoView({ block: "center" });
      clickEl(link);
      closed = !!(await isClosed(4000));
    }
    if (!closed) {
      if (!isSelected(findRow())) {
        const cell = findRow()?.querySelector("td[role=gridcell] span.stringcontrol-read");
        if (cell) clickEl(cell);
        await until(() => isSelected(findRow()), 3000);
        await wait(800);
      }
      const ok = getOkBtn();
      if (ok) { ok.focus(); clickEl(ok); ok.click(); }
      closed = !!(await isClosed(3000));
    }
    if (!closed) {
      const cell = findRow()?.querySelector("td[role=gridcell] span.stringcontrol-read");
      if (cell) doubleClick(cell);
      closed = !!(await isClosed(4000));
    }
    if (!closed) throw new Error("Tradelane popup could not be closed automatically.");
    console.log("✅ Tradelane selected");

    const tl = await until(() => tradeLaneShown().includes(norm(R.tradelane)), 8000);
    L("General", { Field: "Trade Lane No.", Value: R.tradelane, Status: tl ? "OK" : "CHECK" });
    await wait(1200);
  }

  // Changing Country Of Origin / Destination makes BC ask "... Do you also want to update the VAT Posting Groups,
  // General Business & Product Posting Groups?" (Yes / No). Nothing else can be entered until it is answered, so
  // answer Yes. Looks only inside that one message dialog (not any "Yes" button on the page) and does nothing if
  // the prompt does not appear (e.g. the value did not actually change).
  async function answerVatPrompt(timeout = 3000) {
    const findDlg = () => [...document.querySelectorAll(".message-dialog")]
      .find(d => sized(d) && /VAT Posting Groups/i.test(d.innerText || ""));
    const dlg = await until(findDlg, timeout, 100);
    if (!dlg) return false;
    const yes = [...dlg.querySelectorAll("button")].find(b => norm(b.textContent) === "yes");
    if (!yes) { L("General", { Field: "VAT Posting Groups prompt", Status: "CHECK — dialog has no Yes button" }); return false; }
    yes.click();
    let gone = await until(() => !dlg.isConnected || !sized(dlg), 2500);
    if (!gone) { realClick(yes); gone = await until(() => !dlg.isConnected || !sized(dlg), 3000); }
    L("General", { Field: "VAT Posting Groups prompt", Value: "Yes",
                   Status: gone ? "OK — answered Yes" : "CHECK — dialog still open after Yes" });
    console.log(gone ? "✅ VAT Posting Groups prompt: Yes" : "⚠ VAT prompt still open");
    await wait(500);
    return true;
  }

  // The moment the customer + trade lane are chosen BC has created the order and its number shows in the card
  // header. Hand it to the platform at once (a console line it saves to the database) so that a failure in any
  // later step still leaves the number behind.
  async function announceFirstOrder() {
    const no = await until(cardNo, 15000);
    if (!no) { L("General", { Field: "TMS No. (new order)", Status: "CHECK — number not shown after the trade lane was selected" }); return; }
    CUR_NO = no;
    L("General", { Field: "TMS No. (new order)", Value: no, Status: "OK" });
    console.log("🔖 FIRST ORDER " + no);
  }

  async function generalTab(R) {
    console.log("\n===== 1) GENERAL =====");
    await customerAndTradelane(R);
    await announceFirstOrder();

    // LEFT column (top → bottom)
    await fill("Container Subtype",      "Go4CTR codContainerSubType", R.containerSubtype, { lookup: true });
    await fill("Customer Ref.",          "ShortcutReference1Code",     R.customerRef);
    await fill("Booking Ref.",           "ShortcutReference2Code",     R.bookingRef);
    await fill("Container No.",          "Go4CTR codContainerNo",      R.containerNo);
    await fill("Vessel Name (Import)",   "Go4CTR Vessel Name Import",  R.vesselName);

    // RIGHT column (top → bottom)
    await fill("Country Of Origin",      "CountryOfOrigin",            R.countryOrigin,  { lookup: true });
    await answerVatPrompt();
    await fill("Country Of Destination", "CountryOfDestination",       R.countryDest,    { lookup: true });
    await answerVatPrompt();
    await fill("Container Type",         "Go4CTR codContainerType",    R.containerType,  { lookup: true });
    await fill("Closing Datetime",       "Go4CTR Closing DateTime",    R.closingDatetime, { date: true });
    await fill("Seal No.",               "Go4CTR Seal No",             R.sealNo);
    await fill("Traction Order",         "Go4CTR Traction Order",      R.tractionOrder);
    await fill("Carrier",                "Go4CTR Carrier No",          R.carrier,        { lookup: true });
    await fill("Depot Out From",         "Go4CTR Depot Out From",      R.depotOutFrom,   { date: true });
    await fill("VGM Closing",            "Go4CTR VGM Closing",         R.vgmClosingDate, { date: true });

    await closeDatePicker();
    blurActive();
    await wait(1500);   // let BC commit the last field
  }

  // =====================================================================
  //  2) ATTACH FILE (same logic as drop.js)
  // =====================================================================
  // prefers a VISIBLE match (the previous order's add-in may still be in the DOM, hidden)
  function findInFrames(selector, win = TOP) {
    try {
      const el = [...win.document.querySelectorAll(selector)].find(e => e.getClientRects().length > 0);
      if (el) return { el, win };
      for (const f of win.document.querySelectorAll("iframe")) {
        const r = findInFrames(selector, f.contentWindow);
        if (r) return r;
      }
    } catch (_) {}
    return null;
  }
  async function waitInFrames(selector, timeout = 20000) {
    const t = Date.now();
    while (Date.now() - t < timeout) {
      const r = findInFrames(selector);
      if (r) return r;
      await wait(300);
    }
    throw new Error("Not found in any frame: " + selector);
  }

  async function attachFile(F) {
    console.log("\n===== 2) ATTACH FILE =====");
    if (!F?.path) { L("File", { Status: "SKIPPED (no file)" }); return; }
    if (typeof JSRunner === "undefined" || !JSRunner.dropFile) {
      L("File", { Field: F.docType, Value: F.path, Status: "SKIPPED — run from JS File Runner" });
      return;
    }
    const zoneSel = `div.docTypedCol#${F.docType}`;
    const { el: zone, win: addinWin } = await waitInFrames(zoneSel);
    zone.scrollIntoView({ block: "center" });
    const rowsBefore = zone.querySelectorAll("tbody tr").length;
    const countRows = () => findInFrames(zoneSel)?.el?.querySelectorAll("tbody tr").length || 0;

    const targets = [zone, zone.querySelector("table.table-library"), addinWin.document.body].filter(Boolean);
    for (const target of targets) {
      try {
        const file = await JSRunner.dropFile(target, F.path);
        console.log(`[tms-drop] Dropped ${file.name} (${file.size} bytes) on <${target.tagName.toLowerCase()}>`);
        if (await until(() => countRows() > rowsBefore, 15000, 500)) {
          L("File", { Field: F.docType, Value: file.name, Status: "OK" });
          await wait(1000);
          return;
        }
        console.log("[tms-drop] No new row yet, trying next target...");
      } catch (e) {
        console.log("[tms-drop] Drop failed on this target: " + e.message);
      }
    }
    L("File", { Field: F.docType, Value: F.path, Status: "CHECK — no new row in " + F.docType });
  }

  // =====================================================================
  //  GRID HELPERS (Lines + Order Cargo)
  // =====================================================================
  function makeGrid(caption) {
    const grid = () => [...document.querySelectorAll("table.ms-nav-grid-data-table")]
      .find(t => vis(t) && norm(t.querySelector("caption")?.textContent) === norm(caption));
    const colIdx = abbr => {
      const t = grid();
      return t ? [...t.querySelectorAll("thead tr:first-child th")]
        .findIndex(th => norm(th.getAttribute("abbr")) === norm(abbr)) : -1;
    };
    const cellText = td => {
      if (!td) return "";
      const inp = td.querySelector("input:not([type=checkbox])");
      return inp ? inp.value : (td.innerText || "");
    };
    const rows = () => [...(grid()?.querySelectorAll("tbody tr[role=row]") || [])];
    const rowByKey = key => rows().find(r => r.getAttribute("rowkey") === key);
    const currentRow = () => rows().find(r => r.classList.contains("real-current"));
    const isCurrent = key => !!rowByKey(key)?.classList.contains("real-current");
    const editableIn = td => {
      const i = td?.querySelector("input:not([type=checkbox])");
      return i && !i.disabled && !i.readOnly && vis(i) ? i : null;
    };
    const val = (key, abbr) => cellText(rowByKey(key)?.cells[colIdx(abbr)]).trim();

    async function activateRow(key, idx) {
      if (isCurrent(key)) return true;
      await closeDatePicker();
      blurActive();
      await wait(400);
      for (let i = 0; i < 3 && !isCurrent(key); i++) {
        const td = rowByKey(key)?.cells[idx];
        if (!td) break;
        td.scrollIntoView({ block: "nearest", inline: "center" });
        const target = td.querySelector("span.stringcontrol-read, a, input") || td;
        realClick(target);
        if (target !== td) realClick(td);
        td.focus?.();
        if (await until(() => isCurrent(key), 2000)) return true;
      }
      const all = rows().map(r => r.getAttribute("rowkey"));
      for (let i = 0; i < all.length && !isCurrent(key); i++) {
        const cur = currentRow();
        const curIdx = all.indexOf(cur?.getAttribute("rowkey"));
        const dir = all.indexOf(key) > curIdx ? ["ArrowDown", 40] : ["ArrowUp", 38];
        const el = editableIn(cur?.cells[idx]) || cur?.cells[idx] || document.activeElement;
        keyEv(el, "keydown", dir[0], dir[0], dir[1]);
        keyEv(el, "keyup",   dir[0], dir[0], dir[1]);
        await until(() => currentRow() !== cur, 1500);
      }
      return isCurrent(key);
    }

    async function cellInput(key, abbr) {
      const idx = colIdx(abbr);
      if (idx < 0) throw new Error(`Column "${abbr}" not found`);
      if (!(await activateRow(key, idx))) throw new Error(`Could not select row ${key}`);
      let inp = await until(() => editableIn(rowByKey(key)?.cells[idx]), 2000);
      if (!inp) {
        const td = rowByKey(key)?.cells[idx];
        if (td) { realClick(td); inp = await until(() => editableIn(rowByKey(key)?.cells[idx]), 2000); }
      }
      if (!inp) throw new Error(`"${abbr}" cell not editable on row ${key}`);
      return inp;
    }

    const nextEditable = (key, fromTd) => {
      const cells = [...(rowByKey(key)?.cells || [])];
      for (let i = cells.indexOf(fromTd) + 1; i < cells.length; i++) {
        const inp = editableIn(cells[i]);
        if (inp) return inp;
      }
      return null;
    };

    async function commitCell(key, abbr, value, opts = {}) {
      const inp = await cellInput(key, abbr);
      const td = inp.closest("td");
      await typeText(inp, value);
      if (opts.lookup) {
        const r = await until(() => findDropdownRow(value), 2500);
        if (r) {
          clickEl(r.querySelector("td a.stringcontrol-read"));
          await until(() => !anyDropdownOpen(), 2500);
        }
      }
      keyEv(inp, "keydown", "Tab", "Tab", 9);
      await wait(150);
      const next = nextEditable(key, td);
      focusOut(inp);
      if (next) { next.focus(); next.dispatchEvent(new FocusEvent("focusin", { bubbles: true })); }
      keyEv(inp, "keyup", "Tab", "Tab", 9);
      await closeDatePicker();
      await wait(opts.settle || 1000);
    }

    // run one cell and log it
    async function step(section, line, key, abbr, value, opts = {}, check) {
      if (!value) return;
      try {
        await commitCell(key, abbr, value, opts);
        const clean = s => norm(s).replace(/[.,]/g, "");
        const ok = check ? await until(check, 6000) : clean(val(key, abbr)).includes(clean(value));
        L(section, { Line: line, Field: abbr, Value: value, Actual: val(key, abbr),
                     Extra: opts.extra ? opts.extra() : "", Status: ok ? "OK" : "CHECK" });
      } catch (e) {
        L(section, { Line: line, Field: abbr, Value: value, Status: e.message });
      }
    }

    return { grid, colIdx, cellText, rows, val, step };
  }

  // =====================================================================
  //  3) LINES
  // =====================================================================
  // Panes (FastTabs) such as Lines and Order Cargo can be collapsed, and a collapsed pane has no grid to fill.
  // Open one only when its grid is missing: clicking the caption of a pane that is already open would CLOSE it.
  async function ensurePane(title, hasGrid) {
    if (hasGrid()) return true;
    const cap = document.querySelector(`.ms-nav-group-caption[role="button"] span[title="${title}"]`)?.closest('[role="button"]');
    if (!cap) return false;
    cap.click();
    L("Pane", { Field: title, Status: "OK — opened (it was collapsed)" });
    console.log(`✅ ${title} panel opened`);
    return !!(await until(hasGrid, 10000));
  }

  async function linesTab(lines) {
    console.log("\n===== 3) LINES =====");
    const G = makeGrid("Lines");
    await ensurePane("Lines", G.grid);
    if (!(await until(G.grid, 5000))) { L("Lines", { Status: "Lines grid not found" }); return; }
    G.grid().scrollIntoView({ block: "center" });
    await wait(500);

    for (const ln of lines) {
      const row = await until(() => {
        const i = G.colIdx("Action Code");
        return G.rows().find(r => norm(G.cellText(r.cells[i])) === norm(ln.action));
      }, 5000);
      if (!row) { L("Lines", { Line: ln.action, Status: "ROW NOT FOUND" }); continue; }
      const key = row.getAttribute("rowkey");

      await G.step("Lines", ln.action, key, "Address No.", ln.addressNo, { lookup: true, settle: 1200,
        extra: () => `${G.val(key, "Address Name")} / ${G.val(key, "Address City")}` },
        () => norm(G.val(key, "Address Name")));
      await G.step("Lines", ln.action, key, "Order Line Ref 1", ln.ref1);
      await G.step("Lines", ln.action, key, "Booked DateTime From", ln.bookedFrom, { settle: 1200,
        extra: () => "Until: " + G.val(key, "Booked DateTime Until") });
      await G.step("Lines", ln.action, key, "Closing Date Time", ln.closing);
    }
    await closeDatePicker();
    blurActive();
    await wait(1000);
  }

  // =====================================================================
  //  4) ORDER CARGO
  // =====================================================================
  async function cargoTab(cargo) {
    console.log("\n===== 4) ORDER CARGO =====");
    const G = makeGrid("Order Cargo");
    await ensurePane("Order Cargo", G.grid);
    if (!(await until(G.grid, 5000))) { L("Cargo", { Status: "Order Cargo grid not found" }); return; }
    G.grid().scrollIntoView({ block: "center" });
    await wait(500);

    for (let n = 0; n < cargo.length; n++) {
      const C = cargo[n];
      const row = await until(() => {
        const i = G.colIdx("Good No.");
        return G.rows().find(r => !norm(G.cellText(r.cells[i])));
      }, 5000);
      if (!row) { L("Cargo", { Line: n + 1, Status: "NO EMPTY CARGO ROW" }); continue; }
      const key = row.getAttribute("rowkey");

      await G.step("Cargo", n + 1, key, "Good No.", C.goodNo, { lookup: true, settle: 1500,
        extra: () => `${G.val(key, "Description")} / ${G.val(key, "Unit of Measure Code")}` },
        () => norm(G.val(key, "Good No.")) === norm(C.goodNo));
      await G.step("Cargo", n + 1, key, "Quantity", C.quantity);
      await G.step("Cargo", n + 1, key, "Gross Weight", C.grossWeight);
    }
    blurActive();
    await wait(1000);
  }

  // =====================================================================
  //  ACTION BAR: Tariffs → Calculate Revenues, Home → Copy Order
  // =====================================================================
  // "shown" works for fixed-position elements (BC action bar + dialogs), unlike offsetParent
  const sized = el => {
    if (!el || !el.isConnected) return false;
    const r = el.getBoundingClientRect();
    return r.width > 2 && r.height > 2 && window.getComputedStyle(el).visibility !== "hidden";
  };
  // really visible on screen: sized, inside the viewport, not hidden by an ancestor, and the top element at its centre
  const shown = el => {
    if (!sized(el)) return false;
    if (el.closest('[aria-hidden="true"], .ms-nav-hidden, [hidden]')) return false;
    const r = el.getBoundingClientRect();
    const x = r.left + r.width / 2, y = r.top + r.height / 2;
    if (x < 0 || y < 0 || x > window.innerWidth || y > window.innerHeight) return false;
    const hit = document.elementFromPoint(x, y);
    return !!hit && (hit === el || el.contains(hit) || hit.contains(el));
  };

  // action bar button by aria-label (prefer the top-level one, e.g. Home tab / Copy Order)
  const actionBtn = label => {
    const all = [...document.querySelectorAll(`button[aria-label="${label}"]`)].filter(shown);
    return all.find(b => b.getAttribute("data-top-level-action") === "true") || all[0] || null;
  };

  async function clickAction(label, timeout = 8000) {
    const b = await until(() => actionBtn(label), timeout);
    if (!b) throw new Error(`Button "${label}" not found`);
    b.scrollIntoView({ block: "nearest" });
    b.focus();
    b.click();
    await wait(800);
    return b;
  }

  // click a tab (Home / Tariffs) until one of its actions is visible
  async function openTab(tab, expectAction) {
    for (let i = 0; i < 3; i++) {
      const t = await until(() => actionBtn(tab), 5000);
      if (!t) throw new Error(`Tab "${tab}" not found`);
      t.scrollIntoView({ block: "nearest" });
      t.focus();
      if (i === 0) t.click(); else realClick(t);
      if (await until(() => actionBtn(expectAction), 3000)) return;
    }
    throw new Error(`"${expectAction}" not visible after opening tab "${tab}"`);
  }

  // BC message boxes (info / confirm) that pop up after an action
  const messageDialog = (exclude) => [...document.querySelectorAll('[role="alertdialog"], [role="dialog"], main.task-dialog, .ms-nav-dialog')]
    .filter(sized)
    .filter(d => !d.matches('form[controlname="Go4TMS Copy Order"]') && !d.closest('form[controlname="Go4TMS Copy Order"]'))
    .find(d => !isCalendar(d) && !(exclude && (d === exclude || exclude.contains(d) || d.contains(exclude))) &&
               [...d.querySelectorAll("button")].some(b => sized(b) && /^(ok|yes|close)$/i.test(norm(b.innerText))));

  // confirm any message that appears (Yes / OK), log its text
  async function handleMessages(section, timeout = 8000, exclude) {
    const t0 = Date.now();
    while (Date.now() - t0 < timeout) {
      const d = messageDialog(exclude);
      if (d) {
        const text = (d.innerText || "").replace(/\s+/g, " ").trim().slice(0, 200);
        const btns = [...d.querySelectorAll("button")].filter(sized);
        const btn = btns.find(b => norm(b.innerText) === "yes") || btns.find(b => norm(b.innerText) === "ok")
                 || btns.find(b => norm(b.innerText) === "close");
        L(section, { Field: "Message", Value: text, Status: "Clicked " + (btn?.innerText.trim() || "?") });
        if (btn) clickEl(btn);
        await until(() => !d.isConnected || !sized(d), 4000);
        await wait(800);
      } else {
        await wait(300);
      }
    }
  }

  async function calculateRevenues() {
    console.log("\n===== 5) CALCULATE REVENUES =====");
    blurActive();
    await wait(1500);                         // let BC save the last cell
    document.querySelector(".ms-nav-content")?.scrollTo?.(0, 0);
    await openTab("Tariffs", "Calculate Revenues");
    await clickAction("Calculate Revenues");
    L("Revenues", { Field: "Calculate Revenues", Status: "Clicked" });
    await handleMessages("Revenues", 10000);
    await openTab("Home", "Copy Order");
  }

  async function copyOrder(copies) {
    console.log(`\n===== 6) COPY ORDER × ${copies} =====`);
    blurActive();
    await wait(1000);
    document.querySelectorAll(".ms-nav-scrollable").forEach(el => { try { el.scrollTop = 0; } catch {} });
    window.scrollTo(0, 0);
    await wait(500);
    await openTab("Home", "Copy Order");
    await clickAction("Copy Order");

    const form = await until(() => [...document.querySelectorAll('form[controlname="Go4TMS Copy Order"]')].filter(sized).pop(), 10000);
    if (!form) throw new Error("Copy Order dialog did not open");

    // No Of Copies
    const qty = form.querySelector('[controlname="No Of Copies"] input');
    if (!qty) throw new Error("No Of Copies field not found");
    await typeText(qty, String(copies));
    pressTab(qty); await wait(100); focusOut(qty);
    await wait(800);
    if (norm(qty.value) !== String(copies)) {           // fallback: set value directly
      qty.focus();
      setter.call(qty, String(copies));
      qty.dispatchEvent(new Event("input",  { bubbles: true }));
      qty.dispatchEvent(new Event("change", { bubbles: true }));
      focusOut(qty);
      await wait(800);
    }
    L("Copy", { Field: "No Of Copies", Value: String(copies), Actual: qty.value, Status: norm(qty.value) === String(copies) ? "OK" : "CHECK" });

    // turn ON every toggle (2 passes: some enable only after another is on, e.g. Use Original File No.)
    for (let pass = 0; pass < 2; pass++) {
      for (const c of form.querySelectorAll(".booleancontrol-toggle-switch-container")) {
        const sw = c.querySelector('.input-wrapper[role="checkbox"]');
        if (!sw || sw.getAttribute("aria-disabled") === "true" || sw.getAttribute("aria-checked") === "true") continue;
        const cbId = sw.querySelector('input[type="checkbox"]')?.id;
        const label = (cbId && form.querySelector(`label[for="${cbId}"]`)) || c.querySelector("label.booleancontrol-toggle-switch") || sw;
        label.click();
        await wait(400);
      }
      await wait(600);
    }
    for (const c of form.querySelectorAll(".booleancontrol-toggle-switch-container")) {
      const sw = c.querySelector('.input-wrapper[role="checkbox"]');
      const name = c.querySelector(".ms-nav-edit-control-caption")?.innerText.trim();
      const on = sw?.getAttribute("aria-checked") === "true";
      const disabled = sw?.getAttribute("aria-disabled") === "true";
      L("Copy", { Field: name, Value: "ON", Actual: on ? "ON" : "OFF", Status: on ? "OK" : (disabled ? "DISABLED" : "CHECK") });
    }

    // OK
    const ok = [...form.querySelectorAll(".ms-nav-actionbar-container button")].find(b => sized(b) && norm(b.innerText) === "ok");
    if (!ok) throw new Error("OK button not found in Copy Order dialog");
    clickEl(ok);
    const closed = await until(() => !form.isConnected || !sized(form), 20000);
    L("Copy", { Field: "OK", Status: closed ? "Dialog closed" : "CHECK — dialog still open" });
    if (!closed) throw new Error("Copy Order dialog did not close after OK");
  }

  // =====================================================================
  //  7) "TMS Copy Orders Overviews" → note the order Nos, click Close
  // =====================================================================
  const overviewDlg = () => [...document.querySelectorAll('[role="dialog"], main.task-dialog')]
    .filter(sized)
    .find(d => /tms copy orders overview/i.test(d.querySelector('[role="heading"], .native-container-title, [title]')?.textContent || d.innerText.slice(0, 200)));

  async function closeOverview() {
    console.log("\n===== 7) COPY ORDERS OVERVIEW =====");
    const d = await until(overviewDlg, 20000);
    if (!d) { L("Overview", { Status: "CHECK — overview pane did not appear" }); return []; }
    await wait(1500);
    // order Nos from the first grid of the pane (No. column)
    const grid = [...d.querySelectorAll("table.ms-nav-grid-data-table")][0];
    const nos = [...(grid?.querySelectorAll("tbody tr[role=row]") || [])].map(r => {
      for (const td of r.cells) {
        const t = ((td.querySelector("input")?.value) || td.innerText || "").trim();
        if (/^\d{6,}$/.test(t)) return t;
      }
      return null;
    }).filter(Boolean);
    L("Overview", { Field: "Orders", Value: nos.join(", "), Status: nos.length ? "OK" : "CHECK — no Nos read" });
    const close = [...d.querySelectorAll("button")].filter(sized).find(b => norm(b.innerText) === "close");
    if (!close) throw new Error('"Close" button not found in Copy Orders Overviews');
    close.click();
    if (!(await until(() => !overviewDlg(), 8000))) { realClick(close); await until(() => !overviewDlg(), 8000); }
    await wait(1500);
    return nos;
  }

  // =====================================================================
  //  8) File No. from the card   9) Back to the list
  // =====================================================================
  async function readFileNo() {
    const get = () => {
      const c = [...document.querySelectorAll('.ms-nav-edit-control-container[controlname="Go4CTR File No"]')].filter(sized).pop();
      return (c?.querySelector("a.stringcontrol-read, .stringcontrol-read")?.textContent || c?.querySelector("input")?.value || "").replace(/\u00a0/g, " ").trim();
    };
    const fileNo = await until(get, 15000);
    if (!fileNo) throw new Error("File No. is empty on the card");
    L("File No.", { Field: "File No.", Value: fileNo, Status: "OK" });
    console.log("📁 File No.: " + fileNo);
    return fileNo;
  }

  const filterBtn = () => [...document.querySelectorAll('button[aria-label="Add a new filter on a field"]')].filter(sized).pop() || null;
  // "Filter list by..." caption button (collapsed state) — enabled only while collapsed
  const filterListByBtn = () => [...document.querySelectorAll(".caption-panel--KorW_IDhdQGYa79B button, [class*='caption-panel'] button")]
    .filter(b => sized(b) && !b.disabled && /^filter list by/i.test((b.innerText || "").trim())).pop() || null;
  const listOpenLinks = () => [...document.querySelectorAll('a[title^="Open record"]')].filter(sized);

  async function backToList() {
    console.log("\n===== 9) BACK TO LIST =====");
    blurActive();
    await wait(1500);
    const back = [...document.querySelectorAll('button[title="Back"]')].filter(sized).pop();
    if (!back) throw new Error('"Back" button not found');
    back.click();
    const ok = await until(() => {
      if (filterBtn() || (listOpenLinks().length && !cardNo())) return true;
      const w = findWindow(d => hasSized(d, 'button[aria-label="Add a new filter on a field"]') || hasSized(d, 'a[title^="Open record"]'));
      if (w && w !== W) { rebind(w); return true; }
      return false;
    }, 15000);
    if (!ok) throw new Error("Orders list did not appear after Back");
    await wait(1500);
  }

  // =====================================================================
  //  10) Filter the list: + Filter → File No. → value → Enter
  // =====================================================================
  const fileNoFilterInput = () => [...document.querySelectorAll(
      '.filter-lines-container .advanced-list-filter-line [controlname="File No."] input')].filter(sized).pop() || null;
  const optText = o => (o.querySelector(".ms-ComboBox-optionText")?.textContent || o.innerText || "").replace(/\s+/g, " ").trim();
  const fieldOptions = () => [...document.querySelectorAll('[role="option"]')].filter(sized);
  const fileNoOption = () => fieldOptions().find(o => norm(optText(o)) === "file no.");   // exact — not "Original File No."
  // the field picker combobox that "+ Filter..." opens in the filter pane
  const pickerCombo = () => [...document.querySelectorAll(
      '.filter-pane-container input[role="combobox"], [class*="filter-pane"] input[role="combobox"], input[role="combobox"][aria-expanded="true"]')]
    .filter(sized).pop() || null;

  // make sure the filter pane is open and "+ Filter..." is visible
  async function showFilterButton() {
    if (filterBtn()) return filterBtn();
    // collapsed: "Filter list by..." → click it
    const cap = filterListByBtn();
    if (cap) { cap.click(); if (await until(filterBtn, 3000)) return filterBtn(); realClick(cap); if (await until(filterBtn, 3000)) return filterBtn(); }
    // pane closed: funnel / "Show filter pane" button in the action bar
    const pane = [...document.querySelectorAll(
        'button[aria-label*="filter pane" i], button[title*="filter pane" i], button[aria-label="Toggle filter" i], button[title="Toggle filter" i]')]
      .filter(sized)[0];
    if (pane) {
      pane.click();
      await until(() => filterBtn() || filterListByBtn(), 4000);
      const cap2 = filterListByBtn();
      if (!filterBtn() && cap2) { cap2.click(); await until(filterBtn, 3000); }
    }
    return filterBtn();
  }

  // "+ Filter..." → pick "File No." in the field list
  async function pickFileNoField() {
    const fb = await showFilterButton();
    if (!fb) throw new Error('"+ Filter..." button not found (filter pane closed?)');
    fb.click();
    let opt = await until(fileNoOption, 2500);
    const combo = await until(pickerCombo, 2500);
    if (!opt && combo) {                               // list not open → open it (chevron / Alt+Down)
      const chevron = combo.closest(".ms-ComboBox")?.querySelector("button");
      if (chevron && sized(chevron)) chevron.click();
      else { keyEv(combo, "keydown", "ArrowDown", "ArrowDown", 40); }
      opt = await until(fileNoOption, 2000);
    }
    if (!opt && combo) {                               // type to narrow the list
      await typeText(combo, "File No.");
      opt = await until(fileNoOption, 2500);
    }
    if (opt) {
      opt.scrollIntoView({ block: "nearest" });
      opt.click();
      if (!(await until(fileNoFilterInput, 3000))) { realClick(opt); await until(fileNoFilterInput, 3000); }
    } else if (combo && norm(combo.value) === "file no.") {
      pressEnter(combo);                               // typed text matches → Enter selects it
      await until(fileNoFilterInput, 3000);
    }
    const input = fileNoFilterInput();
    if (!input) {
      console.warn("Field options seen:", fieldOptions().map(optText));
      throw new Error('"File No." not found in the filter field list (see "Field options seen" above)');
    }
    return input;
  }

  async function filterByFileNo(fileNo) {
    console.log("\n===== 10) FILTER LIST BY FILE NO. =====");
    let input = fileNoFilterInput();                   // already a File No. line → reuse it
    if (!input) input = await pickFileNoField();
    input.focus();
    setter.call(input, fileNo);
    input.dispatchEvent(new Event("input",  { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
    await wait(300);
    pressEnter(input);
    // wait until every visible row shows this File No.
    const ok = await until(() => {
      const rows = listRows();
      return rows.length && rows.every(r => (r.innerText || "").includes(fileNo)) ? rows.length : 0;
    }, 15000);
    if (!ok) {
      // File No. column may not be shown on the list → accept the rows once the list settles
      await wait(3000);
      const rows = listRows();
      if (!rows.length) throw new Error(`No orders found for File No. ${fileNo}`);
      if (rows.some(r => (r.innerText || "").includes(fileNo)))
        throw new Error(`List did not filter to File No. ${fileNo}`);
      L("Filter", { Field: "File No.", Value: fileNo, Status: "CHECK — File No. column not on list, could not confirm filter" });
      return rows.length;
    }
    await wait(1000);
    L("Filter", { Field: "File No.", Value: fileNo, Actual: `${ok} order(s)`, Status: "OK" });
    console.log(`✅ ${ok} order(s) for ${fileNo}`);
    return ok;
  }

  // =====================================================================
  //  11) EDIT: ⋮ → Edit on row 1 → Container No. + Seal No. → check Lines → Next
  // =====================================================================
  const fieldValue = cn => {
    const c = container(cn);
    if (!c) return "";
    const i = c.querySelector("input:not([type=checkbox]):not([type=hidden])");
    return (i ? i.value : c.querySelector(".stringcontrol-read")?.innerText || "").trim();
  };
  // The TMS ORDER NUMBER = the leading digits of the card header's title. Read from there, not from
  // the File No.: a single order may never get a File No. (The generated hashes after "--" can change
  // with a Business Central release, so the stable class-name prefixes are tried too, then the heading.)
  const cardNo = () => {
    for (const sel of ['.secondary-row--OKG79b9vwIblz3DS .title--m8MvvpvUuMfMrmvJ',
                       '[class*="secondary-row--"] [class*="title--"]']) {
      for (const el of document.querySelectorAll(sel)) {
        if (!sized(el)) continue;
        const m = (el.textContent || "").trim().match(/^\d+/);
        if (m) return m[0];
      }
    }
    const h = [...document.querySelectorAll('[role="heading"][aria-level="2"]')]
      .filter(sized).map(e => (e.innerText || "").trim()).find(t => /^\d{6,}\b/.test(t));
    return h ? h.match(/^\d+/)[0] : "";
  };
  const cardReady = () => {
    if (cardNo() && container("Go4CTR codContainerNo")) return true;
    const w = findWindow(d => hasSized(d, '.ms-nav-edit-control-container[controlname="Go4CTR codContainerNo"]'));
    if (w && w !== W) { rebind(w); return !!(cardNo() && container("Go4CTR codContainerNo")); }
    return false;
  };
  const editBtn = () => [...document.querySelectorAll(
      'button[aria-label="Edit"], button[title="Edit"], button[title^="Make changes"], button[aria-label^="Make changes"], button[title^="Edit the"]')]
    .filter(sized).pop() || null;
  async function ensureEdit() {
    if (getInput("Go4CTR codContainerNo")) return;
    const b = await until(editBtn, 4000);
    if (!b) throw new Error("Card is read-only and the Edit (pencil) button was not found");
    b.click();
    if (!(await until(() => getInput("Go4CTR codContainerNo"), 8000))) {
      realClick(b);
      if (!(await until(() => getInput("Go4CTR codContainerNo"), 8000))) throw new Error("Card did not switch to edit mode");
    }
    await wait(800);
  }
  async function setField(label, cn, value) {
    if (!value) return;
    const el = await until(() => getInput(cn), 6000);
    if (!el) { L("Edit", { Field: label, Value: value, Status: "NOT FOUND / READ-ONLY" }); return; }
    await typeText(el, value);
    pressTab(el); await wait(100); focusOut(el);
    await wait(1200);
    const now = fieldValue(cn);
    L("Edit", { Field: label, Value: value, Actual: now, Status: norm(now) === norm(value) ? "OK" : "CHECK" });
  }
  function checkLines() {
    const t = [...document.querySelectorAll("table.ms-nav-grid-data-table")]
      .find(x => vis(x) && norm(x.querySelector("caption")?.textContent) === "lines");
    if (!t) { L("Check", { Status: "Lines grid not found" }); return; }
    const heads = [...t.querySelectorAll("thead tr:first-child th")].map(th => norm(th.getAttribute("abbr")));
    const cell = (r, abbr) => {
      const td = r.cells[heads.indexOf(norm(abbr))];
      if (!td) return null;
      const inp = td.querySelector("input:not([type=checkbox])");
      return (inp ? inp.value : td.innerText || "").replace(/\u00a0/g, " ").trim();
    };
    let count = 0;
    for (const r of t.querySelectorAll("tbody tr[role=row]")) {
      const action = cell(r, "Action Code");
      if (!action) continue;
      count++;
      const need = REQUIRED[action.toUpperCase()] || REQUIRED["*"];
      const missing = [], notShown = [];
      for (const abbr of need) { const v = cell(r, abbr); if (v === null) notShown.push(abbr); else if (!v) missing.push(abbr); }
      L("Check", {
        Line: action,
        Field: `${cell(r, "Address No.") || "-"} ${cell(r, "Address Name") || ""}`.trim(),
        Actual: `Ref1: ${cell(r, "Order Line Ref 1") || "-"} | Booked: ${cell(r, "Booked DateTime From") || "-"} | Closing: ${cell(r, "Closing Date Time") || "-"}`,
        Status: missing.length ? "MISSING: " + missing.join(", ") : (notShown.length ? "OK (column hidden: " + notShown.join(", ") + ")" : "OK"),
      });
    }
    if (!count) L("Check", { Status: "NO LINES" });
  }
  const listRows = () => {
    const t = [...document.querySelectorAll("table.ms-nav-grid-data-table")]
      .find(x => sized(x) && !/^lookupform/i.test(x.querySelector("caption")?.textContent || "")
                 && x.querySelector('a[title^="Open record"]'));
    return [...(t?.querySelectorAll("tbody tr[role=row]") || [])].filter(r => r.querySelector('a[title^="Open record"]'));
  };
  const editItem = () => [...document.querySelectorAll('li[role="menuitem"]')]
    .filter(sized).find(li => norm(li.querySelector(".ms-nav-ctxmenu-title")?.textContent) === "edit");

  async function openFirstRow() {
    const row = listRows()[0];
    if (!row) throw new Error("No order rows on the list");
    const link = row.querySelector('a[title^="Open record"]');
    const no = link.textContent.trim();
    console.log("→ opening " + no + " via ⋮ → Edit");
    row.scrollIntoView({ block: "center" });
    for (let i = 0; i < 3 && !cardReady(); i++) {
      let menu = row.querySelector('a[title="Show more options"]');
      if (!menu || !sized(menu)) {
        realClick(row.cells[2] || row.cells[0]);
        await wait(500);
        menu = row.querySelector('a[title="Show more options"]');
      }
      if (!menu) throw new Error('"Show more options" (⋮) not found on the first row');
      if (i === 0) menu.click(); else realClick(menu);
      const item = await until(editItem, 3000);
      if (!item) continue;
      item.click();
      if (await until(cardReady, 10000)) break;
    }
    if (!cardReady()) throw new Error(`Order card ${no} did not open`);
    await wait(1500);
  }
  const nextBtn = () => [...document.querySelectorAll('[id$="_next_record_button"]')]
    .filter(b => sized(b) && !b.disabled && b.getAttribute("aria-disabled") !== "true").pop() || null;
  async function goNext(prevNo) {
    blurActive();
    await wait(1500);
    const b = await until(nextBtn, 5000);
    if (!b) throw new Error("Next record button not found / disabled (last record?)");
    b.click();
    if (!(await until(() => cardNo() && cardNo() !== prevNo && container("Go4CTR codContainerNo"), 15000)))
      throw new Error("Next record did not load");
    await wait(1500);
  }

  async function editOrders(expectedNos) {
    console.log("\n===== 11) EDIT ORDERS =====");
    await openFirstRow();
    const seen = new Set();
    for (let i = 0; i < CONTAINERS.length; i++) {
      CUR = i + 1;
      const E = CONTAINERS[i];
      if (i > 0) await goNext(CUR_NO);
      CUR_NO = cardNo();
      console.log(`--- order ${CUR}/${CONTAINERS.length} — No. ${CUR_NO} ---`);
      if (seen.has(CUR_NO)) throw new Error(`No. ${CUR_NO} already edited — navigation did not move`);
      seen.add(CUR_NO);
      RESULT.orders[E.containerNo] = CUR_NO;   // container no. -> its own TMS order no.
      if (expectedNos.length && !expectedNos.includes(CUR_NO))
        throw new Error(`No. ${CUR_NO} is not one of this shipment's orders (${expectedNos.join(", ")}) — not editing`);
      await ensureEdit();
      await setField("Container No.", "Go4CTR codContainerNo", E.containerNo);
      await setField("Seal No.",      "Go4CTR Seal No",        E.sealNo);
      blurActive();
      await wait(1000);
      checkLines();
    }
    blurActive();
    await wait(1500);
  }

  // =====================================================================
  //  ONE container: no Copy Order, no list, no filter — the card we are on IS the order.
  //  Its number comes from the card header; a File No. is a bonus (a single order may have none).
  // =====================================================================
  const fileNoNow = () => {
    const c = [...document.querySelectorAll('.ms-nav-edit-control-container[controlname="Go4CTR File No"]')].filter(sized).pop();
    return (c?.querySelector("a.stringcontrol-read, .stringcontrol-read")?.textContent || c?.querySelector("input")?.value || "")
      .replace(/\u00a0/g, " ").trim();
  };
  async function singleOrder() {
    console.log("\n===== 11) SINGLE ORDER (no copy) =====");
    CUR = 1;
    CUR_NO = await until(cardNo, 15000);
    if (!CUR_NO) throw new Error("Could not read the TMS order number from the card header");
    console.log("📌 TMS No.: " + CUR_NO);
    RESULT.orders[CONTAINERS[0].containerNo] = CUR_NO;
    // Container No. + Seal No. were typed in the General step (one container: no rows to find, nothing to edit
    // afterwards). Read them back so a value BC dropped or changed is reported, not assumed.
    blurActive();
    await wait(1000);
    const want = CONTAINERS[0], gotC = fieldValue("Go4CTR codContainerNo"), gotS = fieldValue("Go4CTR Seal No"), bad = [];
    if (norm(gotC) !== norm(want.containerNo)) bad.push(`Container No. is '${gotC}', expected '${want.containerNo}'`);
    if (want.sealNo && norm(gotS) !== norm(want.sealNo)) bad.push(`Seal No. is '${gotS}', expected '${want.sealNo}'`);
    L("Verify", { Field: "Container / Seal", Value: `${want.containerNo} / ${want.sealNo}`, Actual: `${gotC} / ${gotS}`,
                  Status: bad.length ? "MISMATCH: " + bad.join("; ") : "OK" });
    checkLines();
    const fn = fileNoNow();
    if (fn) { RESULT.fileNo = fn; L("File No.", { Field: "File No.", Value: fn, Status: "OK" }); }
  }

  // =====================================================================
  //  RUN — General → file → Lines → Cargo → Calculate Revenues → (Copy Order …) → edit every order
  // =====================================================================
  const finish = stopped => ({
    ok: !stopped && CONTAINERS.every(c => RESULT.orders[c.containerNo]),
    stopped: stopped || null, orders: RESULT.orders, fileNo: RESULT.fileNo, log,
  });
  CUR = 1;

  try {
    await generalTab(DATA);
  } catch (e) {
    L("General", { Field: "-", Status: "STOPPED: " + e.message });
    console.error("❌ General tab failed — stopping: " + e.message);
    return finish("General tab failed: " + e.message);
  }

  try { await attachFile(DATA.file); }
  catch (e) { L("File", { Status: "ERROR: " + e.message }); }

  try { await linesTab(DATA.lines || []); }
  catch (e) { L("Lines", { Status: "ERROR: " + e.message }); }

  try { await cargoTab(DATA.cargo || []); }
  catch (e) { L("Cargo", { Status: "ERROR: " + e.message }); }

  if (CALC_REVENUES) {
    try { await calculateRevenues(); }
    catch (e) { L("Revenues", { Status: "ERROR: " + e.message }); }
  }

  let stopped = null;
  if (COPIES === 0) {
    try { await singleOrder(); }
    catch (e) {
      L("Flow", { Status: "STOPPED: " + e.message });
      console.error("❌ " + e.message);
      stopped = e.message;
    }
  } else {
    let copied = false;
    try { await copyOrder(COPIES); copied = true; }
    catch (e) { L("Copy", { Status: "STOPPED: " + e.message }); stopped = "Copy Order failed: " + e.message; }

    // 7) → 11): overview, File No., Back, filter, edit every order
    if (copied) {
      try {
        const nos = await closeOverview();
        if (nos.length && nos.length !== CONTAINERS.length)
          L("Overview", { Status: `CHECK — ${nos.length} order(s) in overview but ${CONTAINERS.length} container(s) given` });
        const fileNo = await readFileNo();
        RESULT.fileNo = fileNo;
        await backToList();
        const count = await filterByFileNo(fileNo);
        if (count !== CONTAINERS.length)
          L("Filter", { Status: `CHECK — ${count} order(s) on the list but ${CONTAINERS.length} container(s) given` });
        await editOrders(nos);
      } catch (e) {
        L("Flow", { Status: "STOPPED: " + e.message });
        console.error("❌ " + e.message);
        stopped = e.message;
      }
    }
  }

  console.log("✅ Done.");
  return finish(stopped);
}
